seen=set(); comps=[]
for r in range(R):
 for c in range(C):
  if g[r][c]==2 and (r,c) not in seen:
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    y,x=q.pop(); comp.append((y,x))
    for yy,xx in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
     if 0<=yy<R and 0<=xx<C and g[yy][xx]==2 and (yy,xx) not in seen:
      seen.add((yy,xx));q.append((yy,xx))
   comps.append(comp)
for i,co in enumerate(comps): print(i, (min(r for r,c in co),max(r for r,c in co),min(c for r,c in co),max(c for r,c in co)),len(co),bool(set(co)&lines))

out=[row[:] for row in g]
for co in comps:
 if set(co)&lines:
  for r,c in co:out[r][c]=1
for r,c in lines: out[r][c]=1
print('\n'.join('['+','.join(map(str,row))+'],' for row in out))

